<script lang="ts">
	// Hero landscape: Mt. Hood from Trillium Lake. Decorative only.
	// k values (see transforms) are viewBox units a layer rises by at progress = 1.
	// progress reaches 1 after scrolling 55% of the viewport, by which point the near trees fill what is left of the hero.
	import { MediaQuery } from 'svelte/reactivity';

	let scrollY = $state(0);
	let innerHeight = $state(1);
	const reduceMotion = new MediaQuery('(prefers-reduced-motion: reduce)');
	const progress = $derived(
		reduceMotion.current ? 0 : Math.min(1, Math.max(0, scrollY / (innerHeight * 0.55)))
	);
</script>

